// Validate redirect URL against allowlist
const allowedDomains = ['/', '/dashboard', '/profile', '/settings'];
const referrer = req.get('Referrer') || '/';
let redirectUrl = '/';

try {
  const refUrl = new URL(referrer, `${req.protocol}://${req.get('host')}`);
  const currentHost = req.get('host');

  // Only allow same-origin redirects or paths in allowlist
  if (refUrl.host === currentHost && allowedDomains.includes(refUrl.pathname)) {
    redirectUrl = refUrl.pathname;
  }
} catch (e) {
  // If URL parsing fails, check if it's a safe relative path
  if (allowedDomains.includes(referrer)) {
    redirectUrl = referrer;
  }
}

res.redirect(redirectUrl);

